#### Python Schema Validation Example

```python
import json
from jsonschema import validate, ValidationError
from confluent_kafka import Consumer
from confluent_kafka.schema_registry import SchemaRegistryClient
from confluent_kafka.schema_registry.avro import AvroDeserializer

class SchemaValidator:
    """Validates messages against Schema Registry schemas"""

    def __init__(self, schema_registry_url: str):
        self.schema_registry_client = SchemaRegistryClient({
            'url': schema_registry_url
        })
        self.validation_cache = {}

    def validate_message(self, topic: str, message: dict) -> tuple[bool, list]:
        """
        Validate message against schema
        Returns: (is_valid, error_list)
        """
        errors = []

        # Get schema from registry (with caching)
        schema = self._get_schema(topic)

        # Validate required fields
        for field in schema.get('required', []):
            if field not in message or message[field] is None:
                errors.append(f"Missing required field: {field}")

        # Validate field types
        for field_name, field_value in message.items():
            if field_name in schema.get('properties', {}):
                field_schema = schema['properties'][field_name]

                # Type validation
                expected_type = field_schema.get('type')
                if not self._validate_type(field_value, expected_type):
                    errors.append(
                        f"Invalid type for {field_name}: "
                        f"expected {expected_type}, got {type(field_value).__name__}"
                    )

                # Pattern validation
                if 'pattern' in field_schema and isinstance(field_value, str):
                    import re
                    if not re.match(field_schema['pattern'], field_value):
                        errors.append(
                            f"Field {field_name} does not match pattern: "
                            f"{field_schema.get('errorMessage', field_schema['pattern'])}"
                        )

                # Enum validation
                if 'enum' in field_schema and field_value not in field_schema['enum']:
                    errors.append(
                        f"Invalid value for {field_name}: must be one of "
                        f"{field_schema['enum']}"
                    )

                # Numeric range validation
                if expected_type in ['number', 'integer']:
                    if 'minimum' in field_schema and field_value < field_schema['minimum']:
                        errors.append(
                            f"Field {field_name} below minimum: "
                            f"{field_value} < {field_schema['minimum']}"
                        )
                    if 'maximum' in field_schema and field_value > field_schema['maximum']:
                        errors.append(
                            f"Field {field_name} above maximum: "
                            f"{field_value} > {field_schema['maximum']}"
                        )

        return len(errors) == 0, errors

    def _get_schema(self, topic: str) -> dict:
        """Get schema from registry with caching"""
        if topic not in self.validation_cache:
            # Fetch from Schema Registry
            schema_str = self.schema_registry_client.get_latest_version(
                f"{topic}-value"
            ).schema.schema_str
            self.validation_cache[topic] = json.loads(schema_str)
        return self.validation_cache[topic]

    def _validate_type(self, value, expected_type) -> bool:
        """Validate value matches expected type"""
        if expected_type == 'string':
            return isinstance(value, str)
        elif expected_type == 'integer':
            return isinstance(value, int) and not isinstance(value, bool)
        elif expected_type == 'number':
            return isinstance(value, (int, float)) and not isinstance(value, bool)
        elif expected_type == 'boolean':
            return isinstance(value, bool)
        elif expected_type == 'array':
            return isinstance(value, list)
        elif expected_type == 'object':
            return isinstance(value, dict)
        elif expected_type == 'null':
            return value is None
        return True

# Usage example
validator = SchemaValidator('https://schema-registry.example.com')

# Validate message
message = {
    'orderId': 'ORD-1234567890',
    'customerId': 'CUST-12345678',
    'orderDate': 1640995200000,
    'orderAmount': 199.99,
    'orderStatus': 'PENDING',
    'customerEmail': 'customer@example.com'
}

is_valid, errors = validator.validate_message('customer_orders', message)
if not is_valid:
    print(f"Validation failed: {errors}")
```

**Validation Criteria**:
- ✅ All required fields present and non-null
- ✅ Field types match schema definitions
- ✅ Pattern constraints satisfied (regex, format)
- ✅ Enum values within allowed set
- ✅ Numeric values within defined ranges
- ✅ Schema compatibility maintained across versions
- ✅ Invalid messages routed to dead letter queue
- ✅ Validation errors logged with sufficient detail for debugging

