import pytest
import yaml
from typing import Dict, Any

class RuleTestFramework:
    """Framework for testing validation rules"""

    def __init__(self, rule_file_path: str):
        with open(rule_file_path, 'r') as f:
            self.rule_config = yaml.safe_load(f)
        self.rule = self.rule_config['rule']

    def evaluate_rule(self, record: Dict[str, Any]) -> bool:
        """Evaluate rule expression against record"""
        # Parse and execute rule expression
        # This is simplified - real implementation would use safe expression evaluator
        try:
            expression = self.rule['expression']
            # Replace variables with record values
            for key, value in record.items():
                expression = expression.replace(key, str(value))
            # Evaluate (use safe evaluator in production)
            result = eval(expression)
            return result
        except Exception as e:
            print(f"Rule evaluation error: {e}")
            return False

# Pytest test class
class TestCustomerOrderRules:
    """Test cases for customer order validation rules"""

    @pytest.fixture
    def rule_framework(self):
        return RuleTestFramework('business_rules/customer_orders/BR002_tier_limits.yaml')

    def test_bronze_tier_within_limit(self, rule_framework):
        """Test: Bronze tier order within limit should pass"""
        record = {
            'customerId': 'C001',
            'customerTier': 'BRONZE',
            'orderAmount': 450.00
        }
        assert rule_framework.evaluate_rule(record) == True

    def test_bronze_tier_exceeds_limit(self, rule_framework):
        """Test: Bronze tier order exceeding limit should fail"""
        record = {
            'customerId': 'C001',
            'customerTier': 'BRONZE',
            'orderAmount': 600.00
        }
        assert rule_framework.evaluate_rule(record) == False

    def test_silver_tier_boundary(self, rule_framework):
        """Test: Silver tier at exact limit should pass"""
        record = {
            'customerId': 'C002',
            'customerTier': 'SILVER',
            'orderAmount': 2000.00
        }
