#### Python Alert Management

```python
from typing import List, Dict, Any
from datetime import datetime, timedelta
import requests

class AlertManager:
    """Manage data quality alerts and notifications"""

    def __init__(self, config: Dict[str, Any]):
        self.config = config
        self.active_alerts = {}
        self.alert_history = []

    def evaluate_thresholds(
        self,
        topic: str,
        metrics: Dict[str, float]
    ) -> List[Dict[str, Any]]:
        """
        Evaluate metrics against thresholds
        Returns: list of triggered alerts
        """
        triggered_alerts = []

        # Overall quality score
        if metrics.get('overall_score', 100) < 90:
            triggered_alerts.append({
                'alert_name': 'DataQualityCritical',
                'severity': 'critical',
                'topic': topic,
                'message': f"Quality score {metrics['overall_score']}% below critical threshold (90%)",
                'value': metrics['overall_score'],
                'threshold': 90
            })
        elif metrics.get('overall_score', 100) < 95:
            triggered_alerts.append({
                'alert_name': 'DataQualityHigh',
                'severity': 'high',
                'topic': topic,
                'message': f"Quality score {metrics['overall_score']}% below target (95%)",
                'value': metrics['overall_score'],
                'threshold': 95
            })

        # Completeness
        if metrics.get('completeness_pct', 100) < 95:
            triggered_alerts.append({
                'alert_name': 'LowCompleteness',
                'severity': 'medium',
                'topic': topic,
                'message': f"Completeness {metrics['completeness_pct']}% below target (95%)",
                'value': metrics['completeness_pct'],
                'threshold': 95
            })

        # Validation failures
        if metrics.get('validation_failures_per_hour', 0) > 100:
            triggered_alerts.append({
                'alert_name': 'HighValidationFailureRate',
                'severity': 'high',
                'topic': topic,
                'message': f"{metrics['validation_failures_per_hour']} validation failures per hour",
                'value': metrics['validation_failures_per_hour'],
                'threshold': 100
            })

        # Duplicate rate
        duplicate_rate = 100 - metrics.get('uniqueness_pct', 100)
        if duplicate_rate > 5:
            triggered_alerts.append({
                'alert_name': 'HighDuplicateRate',
                'severity': 'medium',
                'topic': topic,
                'message': f"{duplicate_rate}% duplicate rate",
                'value': duplicate_rate,
                'threshold': 5
            })

        return triggered_alerts

    def send_alert(self, alert: Dict[str, Any]):
        """Send alert notification"""
        alert_key = f"{alert['alert_name']}:{alert['topic']}"

        # Check if already alerting (deduplication)
        if alert_key in self.active_alerts:
            last_alert_time = self.active_alerts[alert_key]['timestamp']
            # Suppress if alerted within last 30 minutes
            if datetime.now() - last_alert_time < timedelta(minutes=30):
                return

        # Record alert
        alert['timestamp'] = datetime.now()
        self.active_alerts[alert_key] = alert
        self.alert_history.append(alert)

        # Route alert based on severity
        if alert['severity'] == 'critical':
            self._send_pagerduty(alert)
            self._send_slack(alert, '#data-quality-critical')
        elif alert['severity'] == 'high':
            self._send_slack(alert, '#data-quality-alerts')
        elif alert['severity'] == 'medium':
            self._send_slack(alert, '#data-quality-alerts')
        else:
            self._send_email(alert)

    def resolve_alert(self, alert_name: str, topic: str):
        """Mark alert as resolved"""
        alert_key = f"{alert_name}:{topic}"

        if alert_key in self.active_alerts:
            resolved_alert = self.active_alerts[alert_key]
            resolved_alert['resolved_at'] = datetime.now()
            resolved_alert['duration'] = (
                resolved_alert['resolved_at'] - resolved_alert['timestamp']
            ).total_seconds() / 60  # minutes

            # Send resolution notification
            self._send_slack_resolution(resolved_alert, '#data-quality-alerts')

            # Remove from active alerts
            del self.active_alerts[alert_key]

    def _send_pagerduty(self, alert: Dict[str, Any]):
        """Send PagerDuty alert"""
        payload = {
            'routing_key': self.config['pagerduty_service_key'],
            'event_action': 'trigger',
            'dedup_key': f"{alert['alert_name']}:{alert['topic']}",
            'payload': {
                'summary': alert['message'],
                'severity': 'critical',
                'source': alert['topic'],
                'custom_details': {
                    'value': alert['value'],
                    'threshold': alert['threshold'],
                    'timestamp': alert['timestamp'].isoformat()
                }
            }
        }

        requests.post(
            'https://events.pagerduty.com/v2/enqueue',
            json=payload
        )

    def _send_slack(self, alert: Dict[str, Any], channel: str):
        """Send Slack notification"""
        severity_emoji = {
            'critical': ':rotating_light:',
            'high': ':warning:',
            'medium': ':large_orange_diamond:',
            'low': ':information_source:'
        }

        message = {
            'channel': channel,
            'username': 'Data Quality Alerts',
            'icon_emoji': severity_emoji.get(alert['severity'], ':bell:'),
            'text': f"{severity_emoji[alert['severity']]} *{alert['alert_name']}*",
            'blocks': [
                {
                    'type': 'section',
                    'text': {
                        'type': 'mrkdwn',
                        'text': f"*Topic:* {alert['topic']}\n*Message:* {alert['message']}"
                    }
                },
                {
                    'type': 'section',
                    'text': {
                        'type': 'mrkdwn',
                        'text': f"*Value:* {alert['value']}\n*Threshold:* {alert['threshold']}"
                    }
                }
            ]
        }

        requests.post(self.config['slack_webhook'], json=message)

    def _send_slack_resolution(self, alert: Dict[str, Any], channel: str):
        """Send Slack resolution notification"""
        message = {
            'channel': channel,
            'username': 'Data Quality Alerts',
            'icon_emoji': ':white_check_mark:',
            'text': f":white_check_mark: *Resolved: {alert['alert_name']}*",
            'blocks': [
                {
                    'type': 'section',
                    'text': {
                        'type': 'mrkdwn',
                        'text': f"*Topic:* {alert['topic']}\n*Duration:* {alert['duration']:.1f} minutes"
                    }
                }
            ]
        }

        requests.post(self.config['slack_webhook'], json=message)

    def _send_email(self, alert: Dict[str, Any]):
        """Send email notification"""
        # Email implementation (placeholder)
        pass

# Usage example
alert_mgr = AlertManager(config={
    'pagerduty_service_key': 'DQ_CRITICAL_SERVICE_KEY',
    'slack_webhook': 'https://hooks.slack.com/services/...'
})

# Evaluate metrics
metrics = {
    'overall_score': 92.5,
    'completeness_pct': 93.0,
    'uniqueness_pct': 98.0,
    'validation_failures_per_hour': 150
}

triggered_alerts = alert_mgr.evaluate_thresholds('customer_orders', metrics)

# Send alerts
for alert in triggered_alerts:
    alert_mgr.send_alert(alert)

# Later: Resolve when metrics improve
alert_mgr.resolve_alert('DataQualityHigh', 'customer_orders')
```

**Validation Criteria**:
- ✅ Threshold-based alerts triggered when metrics cross thresholds
- ✅ Trend-based alerts detect declining quality over time
- ✅ Alert severity levels defined (critical, high, medium, low)
- ✅ Critical alerts sent to PagerDuty for immediate response
- ✅ High/medium alerts sent to Slack for team awareness
- ✅ Low severity alerts sent via email
- ✅ Alert deduplication prevents alert fatigue (30-minute suppression)
- ✅ Resolution notifications sent when issues resolve
- ✅ Alert history tracked for analysis
- ✅ Dashboard links included in alerts for context

